      "assessment": {
        "nobel_worthiness": "Quantum cryptography established that fundamental quantum principles can enable qualitatively new secure communication.",
        "attribution": "Bennett and Brassard pioneered quantum key distribution, and Ekert introduced a foundational entanglement-based formulation.",
        "maturity": "Security principles and practical implementations have been tested over decades.",
        "uncertainties": [
          "The discovery is partly an information-science advance, and the appropriate physics framing requires deliberation."
        ]
      }
    }
